// Filter recruiters eligible for follow-up today
const allRows = $input.all();
const todayStr = new Date().toISOString().split('T')[0];
const eligible = [];

const terminalStatuses = ['Replied', 'Interview', 'Closed', 'Do Not Contact', 'Failed'];

for (const item of allRows) {
  const row = item.json;
  const status = String(row.Status || '').trim();
  const replyStatus = String(row.ReplyStatus || '').trim();
  const followUpDate = String(row.FollowUpDate || '').trim();
  const followUpCount = parseInt(row.FollowUpCount || '0', 10);
  const threadId = String(row.GmailThreadID || '').trim();

  // 1. Status Filter
  if (terminalStatuses.includes(status) || replyStatus === 'Replied') continue;
  if (status !== 'Sent' && status !== 'Follow-up 1') continue;

  // 2. Count limit
  if (followUpCount >= 2) continue;

  // 3. Due Date Check (FollowUpDate <= today)
  if (!followUpDate || followUpDate > todayStr) continue;

  // 4. Must have a valid thread ID
  if (!threadId) continue;

  eligible.push({
    json: {
      ...row,
      CurrentFollowUpCount: followUpCount,
      ThreadId: threadId
    }
  });
}

return eligible;

const threadResult = $input.first().json;
const recruiter = $('Loop Over Due Recruiters').first().json;
const configNode = $('Global Configuration').first().json;

const config = {
  TEST_MODE: configNode.TEST_MODE === 'true' || configNode.TEST_MODE === true,
  TEST_EMAIL: configNode.TEST_EMAIL || 'saitarrunpitta@gmail.com',
  FOLLOW_UP_2_DAYS: parseInt(configNode.FOLLOW_UP_2_DAYS || '7', 10),
  DELAY_BETWEEN_EMAILS_SECONDS: parseInt(configNode.DELAY_BETWEEN_EMAILS_SECONDS || '90', 10)
};

const now = new Date();
const nowIso = now.toISOString();

// Check for replies in thread
let replyDetected = false;
let autoResponder = false;

if (threadResult && threadResult.messages && Array.isArray(threadResult.messages)) {
  for (const msg of threadResult.messages) {
    const fromHeader = String(msg.from || msg.sender || '').toLowerCase();
    const snippet = String(msg.snippet || '').toLowerCase();

    // If message is NOT from Sai Tarrun Pitta
    if (fromHeader && !fromHeader.includes('saitarrunpitta@gmail.com')) {
      // Check for common auto-responder / out of office patterns
      if (snippet.includes('out of office') || snippet.includes('autoreply') || snippet.includes('automatic reply') || snippet.includes('mailer-daemon')) {
        autoResponder = true;
      } else {
        replyDetected = true;
        break;
      }
    }
  }
}

if (replyDetected) {
  return {
    json: {
      ...recruiter,
      ReplyDetected: true,
      NewStatus: 'Replied',
      NewReplyStatus: 'Replied',
      ReplyDate: nowIso,
      Action: 'Reply Detected'
    }
  };
}

// No reply detected -> Prepare Next Follow-Up
const currentCount = parseInt(recruiter.FollowUpCount || '0', 10);
const nextCount = currentCount + 1;
const firstName = recruiter.FirstName;
const company = recruiter.Company;
const rawEmail = recruiter.Email;

let subject = `Re: Software Engineering Opportunities at ${company} — Sai Tarrun Pitta`;
let plainTextBody = '';
let htmlBody = '';
let nextFollowUpDate = '';
let newStatus = `Follow-up ${nextCount}`;

if (currentCount === 0) {
  // Follow-Up #1
  plainTextBody = `Hi ${firstName},

I wanted to follow up on my previous message regarding Software Engineering opportunities at ${company}.

I'm still very interested in opportunities with the team and would appreciate it if you could take a look at my background when you have a chance.

If there are any roles that could be a good fit, I'd be grateful to be considered or connected with the appropriate hiring team.

Thank you again for your time.

Best,
Sai Tarrun Pitta`;

  htmlBody = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 15px; line-height: 1.6; color: #222222; margin: 0; padding: 0; }
    p { margin: 0 0 16px 0; }
    .signature { margin-top: 24px; border-top: 1px solid #e0e0e0; padding-top: 12px; font-size: 14px; color: #444444; }
  </style>
</head>
<body>
  <p>Hi ${firstName},</p>
  <p>I wanted to follow up on my previous message regarding Software Engineering opportunities at <strong>${company}</strong>.</p>
  <p>I'm still very interested in opportunities with the team and would appreciate it if you could take a look at my background when you have a chance.</p>
  <p>If there are any roles that could be a good fit, I'd be grateful to be considered or connected with the appropriate hiring team.</p>
  <p>Thank you again for your time.</p>
  <p>Best,</p>
  <div class="signature">
    <strong>Sai Tarrun Pitta</strong>
  </div>
</body>
</html>`;

  // Next follow-up in 7 days
  const fuDate = new Date(now.getTime() + config.FOLLOW_UP_2_DAYS * 24 * 60 * 60 * 1000);
  nextFollowUpDate = fuDate.toISOString().split('T')[0];

} else {
  // Follow-Up #2 (Final)
  plainTextBody = `Hi ${firstName},

I wanted to send one final follow-up regarding Software Engineering opportunities at ${company}.

I remain very interested in potentially joining the team and would appreciate any consideration for current or upcoming engineering positions that align with my background.

Thank you for your time.

Best,
Sai Tarrun Pitta`;

  htmlBody = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 15px; line-height: 1.6; color: #222222; margin: 0; padding: 0; }
    p { margin: 0 0 16px 0; }
    .signature { margin-top: 24px; border-top: 1px solid #e0e0e0; padding-top: 12px; font-size: 14px; color: #444444; }
  </style>
</head>
<body>
  <p>Hi ${firstName},</p>
  <p>I wanted to send one final follow-up regarding Software Engineering opportunities at <strong>${company}</strong>.</p>
  <p>I remain very interested in potentially joining the team and would appreciate any consideration for current or upcoming engineering positions that align with my background.</p>
  <p>Thank you for your time.</p>
  <p>Best,</p>
  <div class="signature">
    <strong>Sai Tarrun Pitta</strong>
  </div>
</body>
</html>`;

  nextFollowUpDate = ''; // No more automated follow-ups
}

const targetEmail = config.TEST_MODE ? config.TEST_EMAIL : rawEmail;
const emailSubject = config.TEST_MODE ? `[TEST MODE - To: ${rawEmail}] ${subject}` : subject;

return {
  json: {
    ...recruiter,
    ReplyDetected: false,
    AutoResponderDetected: autoResponder,
    NewStatus: newStatus,
    NewFollowUpCount: nextCount,
    LastEmailDate: nowIso,
    NextFollowUpDate: nextFollowUpDate,
    TargetEmail: targetEmail,
    Subject: emailSubject,
    HtmlBody: htmlBody,
    PlainTextBody: plainTextBody,
    Action: `Follow-up ${nextCount}`,
    DelaySeconds: config.DELAY_BETWEEN_EMAILS_SECONDS
  }
};
